const { ZXFonts8x8 } = await import('./svision/js/platform/canvas2D/zx/zxFonts8x8.js?ver='+window.srcVersion);
// begin code

/**
 * The character set of Pleiads as a svision 8x8 font, in the shape of
 * ZXFonts8x8: the same 96-character set and a glyph table of 16 hex digits per
 * character, so TextEntity, MenuEntity and the ZX dialogs render it like any
 * other font (the Space Invaders pattern, app/spaceInvadersFonts8x8.js there).
 *
 * The table is generated by tools/tiles2font.mjs: 0-9, A-Z, - * and © are the
 * character tiles of the graphics ROM (data/tiles.json, foreground tiles
 * 01h-1Ah, 20h-29h, 2Bh, 1Fh, 2Ch — the letters of INSERT COIN and of the score
 * table, any lit pixel is ink); everything else (punctuation, lowercase) comes
 * from the ZX Spectrum ROM font, the default of ZXFonts8x8, which shares the
 * baseline (rows 1-6). No font of ~/sw/zx-fonts has the Pleiads letters, so
 * unlike Space Invaders there is no sister font to take the rest from.
 *
 * Monospace: 8-pixel cells as on the machine; proportional trims them like
 * the ZX font.
 */
export class PleiadesFonts8x8 extends ZXFonts8x8 {

  /**
   * @param {Object} app - The application instance.
   * @param {boolean} proportional - Trim the glyphs to proportional widths; false keeps the 8-pixel cells.
   */
  constructor(app, proportional) {
    super(app, proportional);
    this.id = 'PleiadesFonts8x8';

    this.setFontsData('');
  } // constructor

} // PleiadesFonts8x8
